'use client'

import { useEffect, useState } from 'react'
import { useTemporalStore } from '@/stores/temporal-store'
import { usePMTilesStore } from '@/stores/pmtiles-store'
import { Button } from '@/components/ui/button'
import { 
  Play, 
  Pause, 
  SkipBack, 
  SkipForward, 
  ChevronLeft, 
  ChevronRight,
  RotateCcw,
  Settings,
  Calendar,
  TrendingUp,
  Layers
} from 'lucide-react'

interface TemporalControlsProps {
  className?: string
}

export function TemporalControls({ className = '' }: TemporalControlsProps) {
  const [showSettings, setShowSettings] = useState(false)
  const [showYearPicker, setShowYearPicker] = useState(false)
  
  const {
    currentYear,
    availableYears,
    isAnimating,
    animationSpeed,
    animationDirection,
    comparisonMode,
    comparisonYear,
    cumulativeMode,
    cumulativeStartYear,
    setCurrentYear,
    startAnimation,
    stopAnimation,
    setAnimationSpeed,
    setAnimationDirection,
    setComparisonMode,
    setComparisonYear,
    setCumulativeMode,
    setCumulativeStartYear,
    goToNextYear,
    goToPreviousYear,
    goToFirstYear,
    goToLastYear,
    canGoNext,
    canGoPrevious,
    getYearRange,
  } = useTemporalStore()
  
  const { metadata } = usePMTilesStore()
  
  // Update available years from metadata
  useEffect(() => {
    if (metadata?.years) {
      useTemporalStore.getState().setAvailableYears(metadata.years)
    }
  }, [metadata])
  
  const yearRange = getYearRange()
  const speedOptions = [
    { value: 2000, label: 'Slow (2s)' },
    { value: 1000, label: 'Normal (1s)' },
    { value: 500, label: 'Fast (0.5s)' },
    { value: 250, label: 'Very Fast (0.25s)' },
  ]
  
  return (
    <div className={`bg-white rounded-lg shadow-lg p-4 ${className}`}>
      {/* Main Controls */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-2">
          {/* Year Display */}
          <div className="flex items-center space-x-1">
            <Calendar className="w-4 h-4 text-gray-500" />
            <button
              onClick={() => setShowYearPicker(!showYearPicker)}
              className="text-2xl font-bold text-gray-900 hover:text-blue-600 transition-colors"
            >
              {currentYear}
            </button>
          </div>
          
          {/* Mode Indicators */}
          <div className="flex items-center space-x-1">
            {comparisonMode && (
              <div className="bg-blue-100 text-blue-800 px-2 py-1 rounded-full text-xs font-medium">
                vs {comparisonYear}
              </div>
            )}
            {cumulativeMode && (
              <div className="bg-green-100 text-green-800 px-2 py-1 rounded-full text-xs font-medium">
                {cumulativeStartYear}-{currentYear}
              </div>
            )}
          </div>
        </div>
        
        {/* Settings Button */}
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowSettings(!showSettings)}
          className="p-2"
        >
          <Settings className="w-4 h-4" />
        </Button>
      </div>
      
      {/* Navigation Controls */}
      <div className="flex items-center justify-center space-x-2 mb-4">
        {/* Go to First */}
        <Button
          variant="outline"
          size="sm"
          onClick={goToFirstYear}
          disabled={!canGoPrevious() || isAnimating}
          className="p-2"
        >
          <SkipBack className="w-4 h-4" />
        </Button>
        
        {/* Previous Year */}
        <Button
          variant="outline"
          size="sm"
          onClick={goToPreviousYear}
          disabled={!canGoPrevious() || isAnimating}
          className="p-2"
        >
          <ChevronLeft className="w-4 h-4" />
        </Button>
        
        {/* Play/Pause */}
        <Button
          variant={isAnimating ? "destructive" : "default"}
          size="sm"
          onClick={isAnimating ? stopAnimation : startAnimation}
          disabled={availableYears.length <= 1}
          className="p-2"
        >
          {isAnimating ? <Pause className="w-4 h-4" /> : <Play className="w-4 h-4" />}
        </Button>
        
        {/* Next Year */}
        <Button
          variant="outline"
          size="sm"
          onClick={goToNextYear}
          disabled={!canGoNext() || isAnimating}
          className="p-2"
        >
          <ChevronRight className="w-4 h-4" />
        </Button>
        
        {/* Go to Last */}
        <Button
          variant="outline"
          size="sm"
          onClick={goToLastYear}
          disabled={!canGoNext() || isAnimating}
          className="p-2"
        >
          <SkipForward className="w-4 h-4" />
        </Button>
      </div>
      
      {/* Year Progress Bar */}
      {yearRange && (
        <div className="mb-4">
          <div className="flex justify-between text-xs text-gray-500 mb-1">
            <span>{yearRange[0]}</span>
            <span>{yearRange[1]}</span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-2">
            <div
              className="bg-blue-600 h-2 rounded-full transition-all duration-300"
              style={{
                width: `${((currentYear - yearRange[0]) / (yearRange[1] - yearRange[0])) * 100}%`
              }}
            />
          </div>
          <div className="flex justify-between text-xs text-gray-400 mt-1">
            {availableYears.map(year => (
              <button
                key={year}
                onClick={() => setCurrentYear(year)}
                className={`w-2 h-2 rounded-full transition-colors ${
                  year === currentYear ? 'bg-blue-600' : 'bg-gray-300 hover:bg-gray-400'
                }`}
                style={{
                  left: `${((year - yearRange[0]) / (yearRange[1] - yearRange[0])) * 100}%`
                }}
              />
            ))}
          </div>
        </div>
      )}
      
      {/* Year Picker Modal */}
      {showYearPicker && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-lg shadow-lg border p-4 z-50">
          <h3 className="font-medium mb-3">Select Year</h3>
          <div className="grid grid-cols-3 gap-2">
            {availableYears.map(year => (
              <button
                key={year}
                onClick={() => {
                  setCurrentYear(year)
                  setShowYearPicker(false)
                }}
                className={`p-2 rounded-md text-sm transition-colors ${
                  year === currentYear
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 hover:bg-gray-200 text-gray-900'
                }`}
              >
                {year}
              </button>
            ))}
          </div>
        </div>
      )}
      
      {/* Settings Panel */}
      {showSettings && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-lg shadow-lg border p-4 z-50">
          <h3 className="font-medium mb-3">Animation Settings</h3>
          
          {/* Animation Speed */}
          <div className="mb-4">
            <label className="block text-sm font-medium mb-2">Speed</label>
            <select
              value={animationSpeed}
              onChange={(e) => setAnimationSpeed(parseInt(e.target.value))}
              className="w-full p-2 border rounded-md text-sm"
            >
              {speedOptions.map(option => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </div>
          
          {/* Animation Direction */}
          <div className="mb-4">
            <label className="block text-sm font-medium mb-2">Direction</label>
            <div className="flex space-x-2">
              <button
                onClick={() => setAnimationDirection('forward')}
                className={`flex-1 p-2 rounded-md text-sm transition-colors ${
                  animationDirection === 'forward'
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 hover:bg-gray-200'
                }`}
              >
                Forward
              </button>
              <button
                onClick={() => setAnimationDirection('backward')}
                className={`flex-1 p-2 rounded-md text-sm transition-colors ${
                  animationDirection === 'backward'
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-100 hover:bg-gray-200'
                }`}
              >
                Backward
              </button>
            </div>
          </div>
          
          {/* Comparison Mode */}
          <div className="mb-4">
            <label className="flex items-center text-sm">
              <input
                type="checkbox"
                checked={comparisonMode}
                onChange={(e) => setComparisonMode(e.target.checked)}
                className="mr-2"
              />
              <Layers className="w-4 h-4 mr-1" />
              Comparison Mode
            </label>
            {comparisonMode && (
              <div className="mt-2">
                <label className="block text-xs text-gray-600 mb-1">Compare with:</label>
                <select
                  value={comparisonYear || ''}
                  onChange={(e) => setComparisonYear(e.target.value ? parseInt(e.target.value) : null)}
                  className="w-full p-1 border rounded text-xs"
                >
                  <option value="">Select year</option>
                  {availableYears
                    .filter(year => year !== currentYear)
                    .map(year => (
                      <option key={year} value={year}>{year}</option>
                    ))}
                </select>
              </div>
            )}
          </div>
          
          {/* Cumulative Mode */}
          <div className="mb-4">
            <label className="flex items-center text-sm">
              <input
                type="checkbox"
                checked={cumulativeMode}
                onChange={(e) => setCumulativeMode(e.target.checked)}
                className="mr-2"
              />
              <TrendingUp className="w-4 h-4 mr-1" />
              Cumulative Mode
            </label>
            {cumulativeMode && (
              <div className="mt-2">
                <label className="block text-xs text-gray-600 mb-1">Start from:</label>
                <select
                  value={cumulativeStartYear || ''}
                  onChange={(e) => setCumulativeStartYear(e.target.value ? parseInt(e.target.value) : null)}
                  className="w-full p-1 border rounded text-xs"
                >
                  <option value="">Select start year</option>
                  {availableYears
                    .filter(year => year <= currentYear)
                    .map(year => (
                      <option key={year} value={year}>{year}</option>
                    ))}
                </select>
              </div>
            )}
          </div>
          
          {/* Reset Button */}
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              setComparisonMode(false)
              setCumulativeMode(false)
              setAnimationSpeed(1000)
              setAnimationDirection('forward')
              stopAnimation()
            }}
            className="w-full"
          >
            <RotateCcw className="w-4 h-4 mr-2" />
            Reset to Defaults
          </Button>
        </div>
      )}
      
      {/* Info */}
      <div className="text-xs text-gray-500 text-center">
        {availableYears.length} years available • {metadata?.totalFiles || 0} PMTiles files
      </div>
    </div>
  )
} 