'use client'

import { useState } from 'react'
import { useResolutionStore } from '@/stores/resolution-store'
import { usePMTilesStore } from '@/stores/pmtiles-store'
import { Button } from '@/components/ui/button'
import { 
  Layers, 
  Settings, 
  Zap, 
  ZapOff, 
  Info,
  Map,
  Building,
  Home,
  MapPin
} from 'lucide-react'

interface ResolutionControlsProps {
  className?: string
}

export function ResolutionControls({ className = '' }: ResolutionControlsProps) {
  const [showDetails, setShowDetails] = useState(false)
  
  const {
    currentResolution,
    autoResolution,
    currentZoom,
    setResolution,
    setAutoResolution,
    getResolutionInfo,
    getResolutionForZoom,
  } = useResolutionStore()
  
  const { getAvailableResolutions, isYearResolutionAvailable } = usePMTilesStore()
  
  const availableResolutions = getAvailableResolutions()
  const currentInfo = getResolutionInfo(currentResolution)
  
  const resolutionIcons = {
    7: Map,
    8: Building,
    9: Home,
    10: MapPin,
  }
  
  const resolutionColors = {
    7: 'bg-red-100 text-red-800',
    8: 'bg-orange-100 text-orange-800',
    9: 'bg-yellow-100 text-yellow-800',
    10: 'bg-green-100 text-green-800',
  }
  
  return (
    <div className={`bg-white rounded-lg shadow-lg p-4 ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center space-x-2">
          <Layers className="w-5 h-5 text-gray-600" />
          <h3 className="font-medium text-gray-900">Resolution</h3>
        </div>
        
        <Button
          variant="outline"
          size="sm"
          onClick={() => setShowDetails(!showDetails)}
          className="p-2"
        >
          <Info className="w-4 h-4" />
        </Button>
      </div>
      
      {/* Current Resolution Display */}
      <div className="mb-4">
        <div className={`inline-flex items-center px-3 py-2 rounded-full text-sm font-medium ${
          resolutionColors[currentResolution as keyof typeof resolutionColors] || 'bg-gray-100 text-gray-800'
        }`}>
          {(() => {
            const IconComponent = resolutionIcons[currentResolution as keyof typeof resolutionIcons]
            return IconComponent ? <IconComponent className="w-4 h-4 mr-2" /> : null
          })()}
          H3 Resolution {currentResolution}
        </div>
        
        <div className="mt-2 text-sm text-gray-600">
          <div className="font-medium">{currentInfo.name}</div>
          <div className="text-xs">{currentInfo.description}</div>
          <div className="text-xs text-gray-500">
            Cell size: {currentInfo.cellSize}
          </div>
        </div>
      </div>
      
      {/* Auto Resolution Toggle */}
      <div className="mb-4">
        <label className="flex items-center text-sm">
          <input
            type="checkbox"
            checked={autoResolution}
            onChange={(e) => setAutoResolution(e.target.checked)}
            className="mr-2"
          />
          {autoResolution ? <Zap className="w-4 h-4 mr-1 text-blue-500" /> : <ZapOff className="w-4 h-4 mr-1 text-gray-400" />}
          Auto-resolution
        </label>
        
        {autoResolution && (
          <div className="mt-2 text-xs text-gray-500">
            <div>Current zoom: {currentZoom.toFixed(1)}</div>
            <div>Suggested resolution: {getResolutionForZoom(currentZoom)}</div>
          </div>
        )}
      </div>
      
      {/* Manual Resolution Selection */}
      {!autoResolution && (
        <div className="mb-4">
          <label className="block text-sm font-medium mb-2">Manual Selection</label>
          <div className="grid grid-cols-2 gap-2">
            {availableResolutions.map(resolution => {
              const info = getResolutionInfo(resolution)
              const IconComponent = resolutionIcons[resolution as keyof typeof resolutionIcons]
              const isAvailable = isYearResolutionAvailable(
                useTemporalStore.getState().currentYear, 
                resolution
              )
              
              return (
                <button
                  key={resolution}
                  onClick={() => setResolution(resolution)}
                  disabled={!isAvailable}
                  className={`p-3 rounded-lg border text-left transition-colors ${
                    resolution === currentResolution
                      ? 'border-blue-500 bg-blue-50 text-blue-900'
                      : isAvailable
                      ? 'border-gray-200 hover:border-gray-300 hover:bg-gray-50'
                      : 'border-gray-100 bg-gray-50 text-gray-400 cursor-not-allowed'
                  }`}
                >
                  <div className="flex items-center mb-1">
                    {IconComponent && <IconComponent className="w-4 h-4 mr-2" />}
                    <span className="font-medium text-sm">Res {resolution}</span>
                  </div>
                  <div className="text-xs">{info.name}</div>
                  <div className="text-xs text-gray-500">{info.cellSize}</div>
                </button>
              )
            })}
          </div>
        </div>
      )}
      
      {/* Resolution Details */}
      {showDetails && (
        <div className="border-t pt-4">
          <h4 className="font-medium text-sm mb-3">Resolution Guide</h4>
          <div className="space-y-3">
            {availableResolutions.map(resolution => {
              const info = getResolutionInfo(resolution)
              const IconComponent = resolutionIcons[resolution as keyof typeof resolutionIcons]
              
              return (
                <div key={resolution} className="flex items-start space-x-3">
                  <div className={`p-2 rounded-lg ${
                    resolutionColors[resolution as keyof typeof resolutionColors] || 'bg-gray-100'
                  }`}>
                    {IconComponent && <IconComponent className="w-4 h-4" />}
                  </div>
                  <div className="flex-1">
                    <div className="text-sm font-medium">
                      H3 Resolution {resolution} - {info.name}
                    </div>
                    <div className="text-xs text-gray-600 mb-1">
                      {info.description}
                    </div>
                    <div className="text-xs text-gray-500">
                      <div>Cell size: {info.cellSize}</div>
                      <div>Zoom range: {info.zoomRange[0]}-{info.zoomRange[1]}</div>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
          
          <div className="mt-4 p-3 bg-blue-50 rounded-lg">
            <div className="text-sm font-medium text-blue-900 mb-1">
              💡 Pro Tip
            </div>
            <div className="text-xs text-blue-700">
              Enable auto-resolution to automatically switch between resolutions based on zoom level. 
              Higher resolutions show more detail but may load slower.
            </div>
          </div>
        </div>
      )}
      
      {/* Current Zoom Info */}
      <div className="text-xs text-gray-500 text-center mt-4">
        Zoom: {currentZoom.toFixed(1)} • {availableResolutions.length} resolutions available
      </div>
    </div>
  )
}

// Import the temporal store for the resolution availability check
import { useTemporalStore } from '@/stores/temporal-store' 